previewCss:
.darma-loader-darma-b13-volcano-erupt { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #fbbf24); width: var(--loader-size, 108px); height: calc(var(--loader-size, 108px) * .84); position: relative; }
.darma-loader-darma-b13-volcano-erupt .darma-loader-darma-b13-volcano-erupt__cone { position: absolute; bottom: 0; left: 12%; width: 76%; height: 54%; clip-path: polygon(37% 0, 63% 0, 100% 100%, 0 100%); background: linear-gradient(#475569, #1e293b); }
.darma-loader-darma-b13-volcano-erupt::after { content: ''; position: absolute; bottom: 50%; left: 40%; width: 20%; height: 8%; border-radius: 50%; background: var(--accent); animation: darma-loader-darma-b13-volcano-erupt-crater calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b13-volcano-erupt span { position: absolute; bottom: 52%; left: 46%; width: 9%; height: 9%; border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 45%, var(--accent-2)), var(--accent)); animation: darma-loader-darma-b13-volcano-erupt-erupt calc(var(--loader-speed, 1s) * 1.8) ease-out infinite; }
.darma-loader-darma-b13-volcano-erupt span:nth-child(1) { --sx: -1; }
.darma-loader-darma-b13-volcano-erupt span:nth-child(2) { --sx: .25; animation-delay: calc(var(--loader-speed, 1s) * .6); }
.darma-loader-darma-b13-volcano-erupt span:nth-child(3) { --sx: 1; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
@keyframes darma-loader-darma-b13-volcano-erupt-erupt { 0% { opacity: 0; transform: translate(0, 0) scale(.4); } 14% { opacity: 1; } 44% { transform: translate(calc(var(--loader-size, 108px) * .1 * var(--sx)), calc(var(--loader-size, 108px) * -.34)) scale(1); } 100% { opacity: 0; transform: translate(calc(var(--loader-size, 108px) * .28 * var(--sx)), calc(var(--loader-size, 108px) * .1)) scale(.65); } }
@keyframes darma-loader-darma-b13-volcano-erupt-crater { 0%, 100% { box-shadow: 0 0 calc(var(--loader-size, 108px) * .05) var(--accent); } 50% { box-shadow: 0 0 calc(var(--loader-size, 108px) * .16) var(--accent-2); } }

